actions.script:
import org.moqui.context.ExecutionContext
ExecutionContext ec = context.ec
def fromD = (fromDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
def thruD = (thruDate ?: fromD)
def ds = java.sql.Timestamp.valueOf(fromD + ' 00:00:00')
def de = java.sql.Timestamp.valueOf(thruD + ' 23:59:59')
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def tf = ec.entity.find("zenith.erp.pos.PosTransaction").condition("statusId","PtCompleted")
    .condition("entryDate","greater-equals",ds).condition("entryDate","less-equals",de)
if (_org) tf.condition("organizationPartyId", _org)
def txnIds = tf.list().collect { it.transactionId }
def pm = new LinkedHashMap()
if (txnIds) {
    ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId","in",txnIds).list().each { it2 ->
        def key = it2.productId ?: it2.productName ?: 'Unknown'
        if (!pm[key]) pm[key] = [pid:(it2.productId ?: ''), pname:(it2.productName ?: it2.productId ?: 'Unknown'), qty:0.0G, amt:0.0G, bills:0]
        pm[key].qty += (it2.quantity ?: 0) as BigDecimal
        pm[key].amt += (it2.lineTotal ?: 0) as BigDecimal
        pm[key].bills++
    }
}
def rows = pm.values().sort { -(it.amt as BigDecimal) }
def stx = (searchText ?: '').trim().toLowerCase()
if (stx) rows = rows.findAll { ((it.pname ?: '').toLowerCase().contains(stx) || (it.pid ?: '').toLowerCase().contains(stx)) }
def esc = { v -> if (v == null) return ""; String s = v.toString().trim(); (s.contains(",")||s.contains("\"")||s.contains("\n")) ? "\"" + s.replace("\"","\"\"") + "\"" : s }
def num = { v -> String.format("%.2f", (v ?: 0.0) as double) }
def intn = { v -> String.format("%d", (long)((v ?: 0) as double)) }
StringBuilder csv = new StringBuilder()
csv.append("ZetaERP - Item Wise Report\n")
csv.append("Period: ${fromD} to ${thruD}  |  Generated: ${ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')}\n\n")
csv.append("Product,Product ID,Qty Sold,Avg Price,Total Amount,Bills\n")
rows.each { r ->
    def avg = r.qty > 0 ? (r.amt / r.qty) : 0.0G
    csv.append("${esc(r.pname)},${esc(r.pid)},${intn(r.qty)},${num(avg)},${num(r.amt)},${r.bills}\n")
}
ec.web.sendTextResponse(csv.toString(), "text/csv", "Item_Wise_${ec.l10n.format(ec.user.nowTimestamp, 'yyyyMMdd_HHmm')}.csv")

def zinr = context.zinr
// ZE-SALES-014 f/u: org-isolate (standalone CSV/PDF render skips the authz filter)
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def _txnFind = ec.entity.find("zenith.erp.pos.PosTransaction")
    .condition("statusId", "PtCompleted")
    .condition("entryDate", "greater-equals", dayStart)
    .condition("entryDate", "less-equals", dayEnd)
if (_org) _txnFind.condition("organizationPartyId", _org)
def txnIds = _txnFind.list().collect { it.transactionId }

itemWiseList = []
totalQty = BigDecimal.ZERO
totalAmount = BigDecimal.ZERO
if (txnIds) {
    def items = ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId","in",txnIds).list()
    def productMap = new LinkedHashMap()
    items.each { item ->
        def key = item.productId ?: item.productName ?: 'Unknown'
        if (!productMap[key]) productMap[key] = [productId: item.productId ?: '',
            productName: item.productName ?: item.productId ?: 'Unknown',
            totalQty: BigDecimal.ZERO, totalAmount: BigDecimal.ZERO, avgPrice: BigDecimal.ZERO, txnCount: 0 as int]
        productMap[key].totalQty += (item.quantity ?: 0) as BigDecimal
        productMap[key].totalAmount += (item.lineTotal ?: 0) as BigDecimal
        productMap[key].txnCount++
    }
    productMap.values().each { p ->
        if (p.totalQty > 0) p.avgPrice = (p.totalAmount / p.totalQty).setScale(2, java.math.RoundingMode.HALF_UP)
        p.qtyStr = zinr.inr(ec.l10n.format(p.totalQty, '#,##0'))
        p.avgStr = zinr.inr(ec.l10n.format(p.avgPrice, '#,##0.00'))
        p.amtStr = zinr.inr(ec.l10n.format(p.totalAmount, '#,##0.00'))
    }
    def rows = productMap.values().sort { -(it.totalAmount as BigDecimal) }
    def stx = (searchText ?: '').trim().toLowerCase()
    if (stx) rows = rows.findAll { ((it.productName ?: '').toLowerCase().contains(stx) || (it.productId ?: '').toLowerCase().contains(stx)) }
    itemWiseList = rows
    totalQty = itemWiseList.inject(0.0G) { a, it -> a + (it.totalQty as BigDecimal) }
    totalAmount = itemWiseList.inject(0.0G) { a, it -> a + (it.totalAmount as BigDecimal) }
}
productsSoldStr = itemWiseList.size().toString()
totalQtyStr = zinr.inr(ec.l10n.format(totalQty, '#,##0'))
totalAmountStr = '₹ ' + zinr.inr(ec.l10n.format(totalAmount, '#,##0.00'))
